func mergeStyle(dst *ResolvedStyle, src *Style) {
	if src == nil {
		return
	}
	if src.Hide != nil {
		dst.Hide = *src.Hide
	}
	if src.Bold != nil {
		dst.Bold = *src.Bold
	}
	if src.Faint != nil {
		dst.Faint = *src.Faint
	}
	if src.Italic != nil {
		dst.Italic = *src.Italic
	}
	if src.Underline != nil {
		dst.Underline = *src.Underline
	}
	if src.BlinkSlow != nil {
		dst.BlinkSlow = *src.BlinkSlow
	}
	if src.BlinkRapid != nil {
		dst.BlinkRapid = *src.BlinkRapid
	}
	if src.Inverse != nil {
		dst.Inverse = *src.Inverse
	}
	if src.Conceal != nil {
		dst.Conceal = *src.Conceal
	}
	if src.CrossOut != nil {
		dst.CrossOut = *src.CrossOut
	}
	if src.Frame != nil {
		dst.Frame = *src.Frame
	}
	if src.Encircle != nil {
		dst.Encircle = *src.Encircle
	}
	if src.Overline != nil {
		dst.Overline = *src.Overline
	}
	if src.Foreground != nil {
		dst.Foreground = *src.Foreground
	}
	if src.Background != nil {
		dst.Background = *src.Background
	}
}

func loadConfig() ResolvedConfig {
	cfg := defaultConfig()

	// Build list of candidate paths in order described
	var candidates []string

	cwd, _ := os.Getwd()
	gopath := os.Getenv("GOPATH")
	if gopath == "" {
		home, _ := os.UserHomeDir()
		if home != "" {
			gopath = filepath.Join(home, "go")
		}
	} else {
		// GOPATH may have multiple entries, take first
		parts := strings.Split(gopath, string(os.PathListSeparator))
		if len(parts) > 0 {
			gopath = parts[0]
		}
	}
	goroot := os.Getenv("GOROOT")
	if goroot == "" {
		goroot = runtime.GOROOT()
	}
	homeDir, _ := os.UserHomeDir()

	// If RICHGO_LOCAL=1, only CWD
	if os.Getenv("RICHGO_LOCAL") == "1" {
		candidates = []string{
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
		}
	} else {
		candidates = []string{
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
			filepath.Join(gopath, ".richstyle"),
			filepath.Join(gopath, ".richstyle.yaml"),
			filepath.Join(gopath, ".richstyle.yml"),
			filepath.Join(goroot, ".richstyle"),
			filepath.Join(goroot, ".richstyle.yaml"),
			filepath.Join(goroot, ".richstyle.yml"),
			filepath.Join(homeDir, ".richstyle"),
			filepath.Join(homeDir, ".richstyle.yaml"),
			filepath.Join(homeDir, ".richstyle.yml"),
		}
	}

	// For removals, we need to accumulate
	var allRemovals []string

	for _, path := range candidates {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		var cf ConfigFile
		if err := yaml.Unmarshal(data, &cf); err != nil {
			// If fails to parse, treat as empty? original richgo would probably still try.
			// Try to also parse if file is empty, we ignore
			continue
		}
		// Merge
		if cf.LabelType != nil {
			cfg.LabelType = strings.ToLower(strings.TrimSpace(*cf.LabelType))
			if cfg.LabelType != "long" && cfg.LabelType != "short" && cfg.LabelType != "none" {
				// keep as is? default to long if unknown
				// but follow what original does: if unknown, maybe default? We'll keep.
			}
		}
		if cf.CoverThreshold != nil {
			cfg.CoverThreshold = *cf.CoverThreshold
		}
		if cf.LeaveTestPrefix != nil {
			cfg.LeaveTestPrefix = *cf.LeaveTestPrefix
		}
		if cf.BuildStyle != nil {
			mergeStyle(&cfg.BuildStyle, cf.BuildStyle)
		}
		if cf.StartStyle != nil {
			mergeStyle(&cfg.StartStyle, cf.StartStyle)
		}
		if cf.PassStyle != nil {
			mergeStyle(&cfg.PassStyle, cf.PassStyle)
		}
		if cf.FailStyle != nil {
			mergeStyle(&cfg.FailStyle, cf.FailStyle)
		}
		if cf.SkipStyle != nil {
			mergeStyle(&cfg.SkipStyle, cf.SkipStyle)
		}
		if cf.FileStyle != nil {
			mergeStyle(&cfg.FileStyle, cf.FileStyle)
		}
		if cf.LineStyle != nil {
			mergeStyle(&cfg.LineStyle, cf.LineStyle)
		}
		if cf.PassPackageStyle != nil {
			mergeStyle(&cfg.PassPackageStyle, cf.PassPackageStyle)
		}
		if cf.FailPackageStyle != nil {
			mergeStyle(&cfg.FailPackageStyle, cf.FailPackageStyle)
		}
		if cf.CoveredStyle != nil {
			mergeStyle(&cfg.CoveredStyle, cf.CoveredStyle)
		}
		if cf.UncoveredStyle != nil {
			mergeStyle(&cfg.UncoveredStyle, cf.UncoveredStyle)
		}
		if len(cf.Removals) > 0 {
			allRemovals = append(allRemovals, cf.Removals...)
		}
	}

	// Compile removals
	for _, pat := range allRemovals {
		re, err := regexp.Compile(pat)
		if err != nil {
			// original binary panics on invalid regex (we saw panic). So we should panic similarly?
			// But for robustness, we could panic to match original.
			panic(fmt.Sprintf("regexp: Compile(`%s`): %v", pat, err))
		}
		cfg.Removals = append(cfg.Removals, re)
	}

	return cfg
}

func colorNameToCode(name string, isBackground bool) (string, bool) {
	lower := strings.ToLower(strings.TrimSpace(name))
	// Check for hex or rgb first
	if strings.HasPrefix(lower, "#") || strings.HasPrefix(lower, "rgb(") {
		return "", false // handle separately
	}
	switch lower {
	case "black":
		if isBackground {
			return "40", true
		}
		return "30", true
	case "red":
		if isBackground {
			return "41", true
		}
		return "31", true
	case "green":
		if isBackground {
			return "42", true
		}
		return "32", true
	case "yellow":
		if isBackground {
			return "43", true
		}
		return "33", true
	case "blue":
		if isBackground {
			return "44", true
		}
		return "34", true
	case "magenta":
		if isBackground {
			return "45", true
		}
		return "35", true
	case "cyan":
		if isBackground {
			return "46", true
		}
		return "36", true
	case "white":
		if isBackground {
			return "47", true
		}
		return "37", true
	case "lightblack", "brightblack", "light black", "bright black", "gray", "grey", "light_black", "bright_black":
		if isBackground {
			return "100", true
		}
		return "90", true
	case "lightred", "brightred", "light red", "bright red", "light_red", "bright_red":
		if isBackground {
			return "101", true
		}
		return "91", true
	case "lightgreen", "brightgreen", "light green", "bright green", "light_green", "bright_green":
		if isBackground {
			return "102", true
		}
		return "92", true
	case "lightyellow", "brightyellow", "light yellow", "bright yellow", "light_yellow", "bright_yellow":
		if isBackground {
			return "103", true
		}
		return "93", true
	case "lightblue", "brightblue", "light blue", "bright blue", "light_blue", "bright_blue":
		if isBackground {
			return "104", true
		}
		return "94", true
	case "lightmagenta", "brightmagenta", "light magenta", "bright magenta", "light_magenta", "bright_magenta":
		if isBackground {
			return "105", true
		}
		return "95", true
	case "lightcyan", "brightcyan", "light cyan", "bright cyan", "light_cyan", "bright_cyan":
		if isBackground {
			return "106", true
		}
		return "96", true
	case "lightwhite", "brightwhite", "light white", "bright white", "light_white", "bright_white":
		if isBackground {
			return "107", true
		}
		return "97", true
	default:
		return "", false
	}
}

func parseHexColor(s string) (int, int, int, bool) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "#") {
		hex := strings.TrimPrefix(s, "#")
		if len(hex) == 3 {
			// expand 3-digit? Not sure if original supports, but we can handle 6-digit only first
			// For simplicity, handle 6-digit
			// Expand 3-digit to 6-digit
			if len(hex) == 3 {
				// e.g., #FFF -> #FFFFFF
				r := string(hex[0]) + string(hex[0])
				g := string(hex[1]) + string(hex[1])
				b := string(hex[2]) + string(hex[2])
				hex = r + g + b
			}
		}
		if len(hex) == 6 {
			r, err1 := strconv.ParseInt(hex[0:2], 16, 0)
			g, err2 := strconv.ParseInt(hex[2:4], 16, 0)
			b, err3 := strconv.ParseInt(hex[4:6], 16, 0)
			if err1 == nil && err2 == nil && err3 == nil {
				return int(r), int(g), int(b), true
			}
		}
		return 0, 0, 0, false
	}
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "rgb(") && strings.HasSuffix(lower, ")") {
		inner := strings.TrimSpace(s[4 : len(s)-1])
		// inner may be like "255,0,0" or "0xFF,0x00,0x00" or "255, 0, 0"
		parts := strings.Split(inner, ",")
		if len(parts) != 3 {
			return 0, 0, 0, false
		}
		var vals [3]int
		for i, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(strings.ToLower(p), "0x") {
				v, err := strconv.ParseInt(p[2:], 16, 0)
				if err != nil {
					return 0, 0, 0, false
				}
				vals[i] = int(v)
			} else {
				v, err := strconv.Atoi(p)
				if err != nil {
					return 0, 0, 0, false
				}
				vals[i] = v
			}
		}
		// Validate 0-255 or 0-256? spec says 0-256, but we clamp
		for _, v := range vals {
			if v < 0 || v > 255 {
				// allow 256? but clamp
			}
		}
		return vals[0], vals[1], vals[2], true
	}
	return 0, 0, 0, false
}

func (s ResolvedStyle) toANSI() string {
	var codes []string
	// Background first? Observation shows background first, then foreground, then decorations
	if s.Background != "" {
		if code, ok := colorNameToCode(s.Background, true); ok {
			codes = append(codes, "\x1b["+code+"m")
		} else if r, g, b, ok := parseHexColor(s.Background); ok {
			codes = append(codes, fmt.Sprintf("\x1b[48;2;%d;%d;%dm", r, g, b))
		}
	}
	if s.Foreground != "" {
		if code, ok := colorNameToCode(s.Foreground, false); ok {
			codes = append(codes, "\x1b["+code+"m")
		} else if r, g, b, ok := parseHexColor(s.Foreground); ok {
			codes = append(codes, fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b))
		}
	}
	if s.Bold {
		codes = append(codes, "\x1b[1m")
	}
	if s.Faint {
		codes = append(codes, "\x1b[2m")
	}
	if s.Italic {
		codes = append(codes, "\x1b[3m")
	}
	if s.Underline {
		codes = append(codes, "\x1b[4m")
	}
	if s.BlinkSlow {
		codes = append(codes, "\x1b[5m")
	}
	if s.BlinkRapid {
		codes = append(codes, "\x1b[6m")
	}
	if s.Inverse {
		codes = append(codes, "\x1b[7m")
	}
	if s.Conceal {
		codes = append(codes, "\x1b[8m")
	}
	if s.CrossOut {
		codes = append(codes, "\x1b[9m")
	}
	if s.Frame {
		codes = append(codes, "\x1b[51m")
	}
	if s.Encircle {
		codes = append(codes, "\x1b[52m")
	}
	if s.Overline {
		codes = append(codes, "\x1b[53m")
	}
	return strings.Join(codes, "")
}

func isTerminal() bool {
	// Check FORCE_COLOR
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	// Check if stdout is terminal
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

// Formatter handles line formatting
type Formatter struct {
	cfg           ResolvedConfig
	enableColor   bool
	lastStyle     *ResolvedStyle
	lastCategory  string // to know parent style for generic
}

func NewFormatter(cfg ResolvedConfig, enableColor bool) *Formatter {
	return &Formatter{
		cfg:         cfg,
		enableColor: enableColor,
	}
}

func (f *Formatter) applyRemovals(s string) string {
	// Apply each removal regex replacing all matches with empty
	for _, re := range f.cfg.Removals {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

func (f *Formatter) formatFileLine(parentStyle ResolvedStyle, rawLine string) string {
	// rawLine is the entire original line with leading spaces preserved? We need to parse file.
	// We attempt to detect file pattern after leading spaces
	// Pattern: (\s*)(.*\.go):(\d+)(?::(\d+))?(.*)
	// We'll use regex
	// But we also need to keep original leading spaces as part of content after label

	// For simplicity, we will split rawLine into leading spaces and rest
	// Use regex to capture
	re := regexp.MustCompile(`^(\s*)(.*\.go):(\d+)(:\d+)?:(.*)$`)
	m := re.FindStringSubmatch(rawLine)
	if m == nil {
		// No file, just apply removals and parent style
		content := f.applyRemovals(rawLine)
		// If after removals content is empty and original was generic log that becomes empty, should we hide?
		// For generic lines, if after removals content trimmed is empty, hide line? Let's check.
		// For "hello log" removal "hello log" -> content becomes "" -> we should hide? Original binary hid it.
		// So if content after removals trimmed is empty, return "" to indicate hide?
		// But for test names empty case, we still show.
		// So we need to distinguish.

		// For generic continuation, if content after removals is empty or whitespace only, hide?
		if strings.TrimSpace(content) == "" {
			// Check if rawLine was originally empty? If raw empty, maybe still hide?
			return ""
		}
		return content
	}
	leading := m[1]
	filePath := m[2]
	lineNum := m[3]
	colPart := m[4] // includes colon if present, e.g., ":5"
	rest := m[5]

	// Rest includes colon? Actually our regex captures rest after line:col, which should start with ":" + message? Let's see groups:
	// Group1: leading \s*
	// Group2: file
	// Group3: line number digits
	// Group4: optional :digits
	// Group5: rest

	// For "    sample_test.go:11: log message":
	// leading "    ", file "sample_test.go", line "11", colPart "", rest ": log message"
	// For "./main_test.go:4:5: x declared":
	// leading "", file "./main_test.go", line "4", colPart ":5", rest ": x declared..."

	// Now apply hide and removals
	// For fileStyle hide, hide file
	// For lineStyle hide, hide line part

	// Also apply removals to file, line, rest? The observed behavior for fileStyle hide removes file but keeps line and rest. For lineStyle hide removes line part.

	// And removals: removal "sample_test.go" removes file substring from content. So removals should be applied before file/line splitting? Or after?

