func (f *Formatter) labelForCategory(category string) (string, string) {
	// Returns long label and short label
	switch category {
	case "build":
		return "BUILD", "!!"
	case "start":
		return "START", ">"
	case "pass":
		return "PASS", "o"
	case "fail":
		return "FAIL", "x"
	case "skip":
		return "SKIP", "-"
	case "cover":
		return "COVER", "%"
	case "passPackage":
		return "PASS", "o"
	case "failPackage":
		return "FAIL", "x"
	case "skipPackage":
		return "SKIP", "-"
	default:
		return "", ""
	}
}

func (f *Formatter) styleForCategory(category string) ResolvedStyle {
	switch category {
	case "build":
		return f.cfg.BuildStyle
	case "start":
		return f.cfg.StartStyle
	case "pass":
		return f.cfg.PassStyle
	case "fail":
		return f.cfg.FailStyle
	case "skip":
		return f.cfg.SkipStyle
	case "cover":
		// covered vs uncovered decided elsewhere
		return f.cfg.CoveredStyle
	case "passPackage":
