func (f *Formatter) formatCover(raw string, percentStr string) (string, bool) {
	cat := "cover"
	// Parse percent
	percent, err := strconv.ParseFloat(percentStr, 64)
	if err != nil {
		percent = 0
	}
	// Determine style based on threshold
	var style ResolvedStyle
	if percent >= float64(f.cfg.CoverThreshold) {
		style = f.cfg.CoveredStyle
	} else {
		style = f.cfg.UncoveredStyle
	}
	if style.Hide {
		return "", true
	}
	f.lastStyle = &style
	f.lastCategory = cat

	// Build bar: 10 chars, # for covered portion
	hashes := int(percent / 10)
	if hashes > 10 {
		hashes = 10
	}
	if hashes < 0 {
		hashes = 0
	}
	bar := strings.Repeat("#", hashes) + strings.Repeat("_", 10-hashes)
	content := fmt.Sprintf("%s%% [%s]", percentStr, bar)

	// Apply removals to content? For cover, removal might apply
	content = f.applyRemovals(content)

	labelLong, labelShort := f.labelForCategory(cat)
	var label string
	switch f.cfg.LabelType {
	case "short":
		padded := fmt.Sprintf("%-2s", labelShort)
		label = padded + " "
	case "none":
		label = ""
	default:
		padded := fmt.Sprintf("%-5s", labelLong)
		label = padded + "| "
	}

	var plain string
	if f.cfg.LabelType == "none" {
		plain = content
	} else {
		plain = label + content
	}

	// Apply removals to final plain line (for consistency)
	for _, re := range f.cfg.Removals {
		plain = re.ReplaceAllString(plain, "")
	}
	if strings.TrimSpace(plain) == "" {
		return "", true
	}

	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	reset := "\x1b[0m"
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + reset, false
}

