func loadConfig() ResolvedConfig {
	cfg := defaultConfig()

	// Build list of candidate paths in order described
	var candidates []string

	cwd, _ := os.Getwd()
	gopath := os.Getenv("GOPATH")
	if gopath == "" {
		home, _ := os.UserHomeDir()
		if home != "" {
			gopath = filepath.Join(home, "go")
		}
	} else {
		// GOPATH may have multiple entries, take first
		parts := strings.Split(gopath, string(os.PathListSeparator))
		if len(parts) > 0 {
			gopath = parts[0]
		}
	}
	goroot := os.Getenv("GOROOT")
	if goroot == "" {
		goroot = runtime.GOROOT()
	}
	homeDir, _ := os.UserHomeDir()

	// If RICHGO_LOCAL=1, only CWD
	if os.Getenv("RICHGO_LOCAL") == "1" {
		candidates = []string{
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
		}
	} else {
		candidates = []string{
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
			filepath.Join(gopath, ".richstyle"),
			filepath.Join(gopath, ".richstyle.yaml"),
			filepath.Join(gopath, ".richstyle.yml"),
			filepath.Join(goroot, ".richstyle"),
			filepath.Join(goroot, ".richstyle.yaml"),
			filepath.Join(goroot, ".richstyle.yml"),
			filepath.Join(homeDir, ".richstyle"),
			filepath.Join(homeDir, ".richstyle.yaml"),
			filepath.Join(homeDir, ".richstyle.yml"),
		}
	}

	// For removals, we need to accumulate
	var allRemovals []string

	for _, path := range candidates {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		var cf ConfigFile
		if err := yaml.Unmarshal(data, &cf); err != nil {
			// If fails to parse, treat as empty? original richgo would probably still try.
			// Try to also parse if file is empty, we ignore
			continue
		}
		// Merge
		if cf.LabelType != nil {
			cfg.LabelType = strings.ToLower(strings.TrimSpace(*cf.LabelType))
			if cfg.LabelType != "long" && cfg.LabelType != "short" && cfg.LabelType != "none" {
				// keep as is? default to long if unknown
				// but follow what original does: if unknown, maybe default? We'll keep.
			}
		}
		if cf.CoverThreshold != nil {
			cfg.CoverThreshold = *cf.CoverThreshold
		}
		if cf.LeaveTestPrefix != nil {
			cfg.LeaveTestPrefix = *cf.LeaveTestPrefix
		}
		if cf.BuildStyle != nil {
			mergeStyle(&cfg.BuildStyle, cf.BuildStyle)
		}
		if cf.StartStyle != nil {
			mergeStyle(&cfg.StartStyle, cf.StartStyle)
		}
		if cf.PassStyle != nil {
			mergeStyle(&cfg.PassStyle, cf.PassStyle)
		}
		if cf.FailStyle != nil {
			mergeStyle(&cfg.FailStyle, cf.FailStyle)
		}
		if cf.SkipStyle != nil {
			mergeStyle(&cfg.SkipStyle, cf.SkipStyle)
		}
		if cf.FileStyle != nil {
			mergeStyle(&cfg.FileStyle, cf.FileStyle)
		}
		if cf.LineStyle != nil {
			mergeStyle(&cfg.LineStyle, cf.LineStyle)
		}
		if cf.PassPackageStyle != nil {
			mergeStyle(&cfg.PassPackageStyle, cf.PassPackageStyle)
		}
		if cf.FailPackageStyle != nil {
			mergeStyle(&cfg.FailPackageStyle, cf.FailPackageStyle)
		}
		if cf.CoveredStyle != nil {
			mergeStyle(&cfg.CoveredStyle, cf.CoveredStyle)
		}
		if cf.UncoveredStyle != nil {
			mergeStyle(&cfg.UncoveredStyle, cf.UncoveredStyle)
		}
		if len(cf.Removals) > 0 {
			allRemovals = append(allRemovals, cf.Removals...)
		}
	}

	// Compile removals
	for _, pat := range allRemovals {
		re, err := regexp.Compile(pat)
		if err != nil {
			// original binary panics on invalid regex (we saw panic). So we should panic similarly?
			// But for robustness, we could panic to match original.
			panic(fmt.Sprintf("regexp: Compile(`%s`): %v", pat, err))
		}
		cfg.Removals = append(cfg.Removals, re)
	}

	return cfg
}

