	// Pattern: coverage with percentage
	if strings.HasPrefix(strings.TrimSpace(raw), "coverage:") {
		// Check if it's percentage
		coverRe := regexp.MustCompile(`coverage:\s+([\d\.]+)% of statements`)
		m := coverRe.FindStringSubmatch(raw)
		if m != nil {
			return f.formatCover(raw, m[1])
		}
		// Otherwise it's "[no statements]" or other, treat as generic continuation
		// Fall through to generic
	}

	// PASS/FAIL/SKIP test lines: optional leading spaces then "--- PASS:" etc
	passFailRe := regexp.MustCompile(`^(\s*)--- (PASS|FAIL|SKIP):\s+(\S+)(.*)$`)
	if m := passFailRe.FindStringSubmatch(raw); m != nil {
		leading := m[1]
		verdict := m[2]
		testName := m[3]
		rest := m[4] // includes duration and maybe other
		// rest is like " (0.00s)" etc
		return f.formatTestResult(leading, verdict, testName, rest)
	}

	// RUN: "=== RUN   TestName"
	runRe := regexp.MustCompile(`^=== RUN\s+(\S+)$`)
	if m := runRe.FindStringSubmatch(raw); m != nil {
		testName := m[1]
		return f.formatRun(testName)
	}

	// PASS bare: "^PASS$"
	if trimmed == "PASS" {
		return f.formatPassPackage(raw)
	}
	// FAIL bare: "^FAIL$"
	if trimmed == "FAIL" {
		return f.formatFailPackageBare(raw)
	}
	// ok package: "^ok\s+"
	if strings.HasPrefix(trimmed, "ok") {
		// Pattern: ok   \t package \t time [ \t coverage...]
		return f.formatOkPackage(raw)
	}
	// FAIL tab package: "^FAIL\s+" or "FAIL\t"
	if strings.HasPrefix(trimmed, "FAIL") && (strings.HasPrefix(raw, "FAIL\t") || strings.HasPrefix(raw, "FAIL ")) {
		// Distinguish from bare FAIL which is exactly "FAIL"
		// If raw == "FAIL", already handled
		// So this is FAIL with package
		return f.formatFailPackage(raw)
	}
	// ? package [no test files]
	if strings.HasPrefix(trimmed, "?") {
		return f.formatQuestionPackage(raw)
	}

	// Generic continuation
	return f.formatGeneric(raw)
}

