		}
		if cf.FailStyle != nil {
			mergeStyle(&cfg.FailStyle, cf.FailStyle)
		}
		if cf.SkipStyle != nil {
			mergeStyle(&cfg.SkipStyle, cf.SkipStyle)
		}
		if cf.FileStyle != nil {
			mergeStyle(&cfg.FileStyle, cf.FileStyle)
		}
		if cf.LineStyle != nil {
			mergeStyle(&cfg.LineStyle, cf.LineStyle)
		}
		if cf.PassPackageStyle != nil {
			mergeStyle(&cfg.PassPackageStyle, cf.PassPackageStyle)
		}
		if cf.FailPackageStyle != nil {
			mergeStyle(&cfg.FailPackageStyle, cf.FailPackageStyle)
		}
		if cf.CoveredStyle != nil {
			mergeStyle(&cfg.CoveredStyle, cf.CoveredStyle)
		}
		if cf.UncoveredStyle != nil {
			mergeStyle(&cfg.UncoveredStyle, cf.UncoveredStyle)
		}
		if len(cf.Removals) > 0 {
			allRemovals = append(allRemovals, cf.Removals...)
		}
	}
	for _, pat := range allRemovals {
		re, err := regexp.Compile(pat)
		if err != nil {
			panic(fmt.Sprintf("regexp: Compile(`%s`): %v", pat, err))
		}
		cfg.Removals = append(cfg.Removals, re)
	}
	return cfg
}

func colorNameToCode(name string, isBackground bool) (string, bool) {
	lower := strings.ToLower(strings.TrimSpace(name))
	if strings.HasPrefix(lower, "#") || strings.HasPrefix(lower, "rgb(") {
		return "", false
	}
	switch lower {
	case "black":
		if isBackground {
			return "40", true
		}
		return "30", true
	case "red":
		if isBackground {
			return "41", true
		}
		return "31", true
	case "green":
		if isBackground {
			return "42", true
		}
		return "32", true
	case "yellow":
		if isBackground {
			return "43", true
		}
		return "33", true
	case "blue":
		if isBackground {
			return "44", true
		}
		return "34", true
	case "magenta":
		if isBackground {
			return "45", true
		}
		return "35", true
	case "cyan":
		if isBackground {
			return "46", true
		}
		return "36", true
	case "white":
		if isBackground {
			return "47", true
		}
		return "37", true
	case "lightblack", "brightblack", "gray", "grey":
		if isBackground {
			return "100", true
		}
		return "90", true
	case "lightred", "brightred":
		if isBackground {
			return "101", true
		}
		return "91", true
	case "lightgreen", "brightgreen":
		if isBackground {
			return "102", true
		}
		return "92", true
	case "lightyellow", "brightyellow":
		if isBackground {
			return "103", true
		}
		return "93", true
	case "lightblue", "brightblue":
		if isBackground {
			return "104", true
