		}
		return "96", true
	case "lightwhite", "brightwhite":
		if isBackground {
			return "107", true
		}
		return "97", true
	default:
		return "", false
	}
}

func parseHexColor(s string) (int, int, int, bool) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "#") {
		hex := strings.TrimPrefix(s, "#")
		if len(hex) == 3 {
			r := string(hex[0]) + string(hex[0])
			g := string(hex[1]) + string(hex[1])
			b := string(hex[2]) + string(hex[2])
			hex = r + g + b
		}
		if len(hex) == 6 {
			r, err1 := strconv.ParseInt(hex[0:2], 16, 0)
			g, err2 := strconv.ParseInt(hex[2:4], 16, 0)
			b, err3 := strconv.ParseInt(hex[4:6], 16, 0)
			if err1 == nil && err2 == nil && err3 == nil {
				return int(r), int(g), int(b), true
			}
		}
		return 0, 0, 0, false
	}
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "rgb(") && strings.HasSuffix(lower, ")") {
		inner := strings.TrimSpace(s[4 : len(s)-1])
		parts := strings.Split(inner, ",")
		if len(parts) != 3 {
			return 0, 0, 0, false
		}
		var vals [3]int
		for i, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(strings.ToLower(p), "0x") {
				v, err := strconv.ParseInt(p[2:], 16, 0)
				if err != nil {
					return 0, 0, 0, false
				}
				vals[i] = int(v)
			} else {
				v, err := strconv.Atoi(p)
				if err != nil {
					return 0, 0, 0, false
				}
				vals[i] = v
			}
		}
		return vals[0], vals[1], vals[2], true
	}
	return 0, 0, 0, false
}

func (s ResolvedStyle) toANSI() string {
	var codes []string
	if s.Background != "" {
		if code, ok := colorNameToCode(s.Background, true); ok {
			codes = append(codes, "\x1b["+code+"m")
		} else if r, g, b, ok := parseHexColor(s.Background); ok {
			codes = append(codes, fmt.Sprintf("\x1b[48;2;%d;%d;%dm", r, g, b))
		}
	}
	if s.Foreground != "" {
		if code, ok := colorNameToCode(s.Foreground, false); ok {
			codes = append(codes, "\x1b["+code+"m")
		} else if r, g, b, ok := parseHexColor(s.Foreground); ok {
			codes = append(codes, fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b))
		}
	}
	if s.Bold {
		codes = append(codes, "\x1b[1m")
	}
	if s.Faint {
		codes = append(codes, "\x1b[2m")
	}
	if s.Italic {
		codes = append(codes, "\x1b[3m")
	}
	if s.Underline {
		codes = append(codes, "\x1b[4m")
	}
	if s.BlinkSlow {
		codes = append(codes, "\x1b[5m")
	}
	if s.BlinkRapid {
		codes = append(codes, "\x1b[6m")
	}
	if s.Inverse {
		codes = append(codes, "\x1b[7m")
	}
	if s.Conceal {
		codes = append(codes, "\x1b[8m")
	}
	if s.CrossOut {
		codes = append(codes, "\x1b[9m")
	}
	if s.Frame {
		codes = append(codes, "\x1b[51m")
	}
	if s.Encircle {
		codes = append(codes, "\x1b[52m")
	}
	if s.Overline {
		codes = append(codes, "\x1b[53m")
	}
	return strings.Join(codes, "")
}

func isTerminal() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

type Formatter struct {
	cfg          ResolvedConfig
	enableColor  bool
	lastStyle    ResolvedStyle
	hasLastStyle bool
}

func NewFormatter(cfg ResolvedConfig, enableColor bool) *Formatter {
	return &Formatter{cfg: cfg, enableColor: enableColor}
}

func (f *Formatter) applyRemovals(s string) string {
	for _, re := range f.cfg.Removals {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

func (f *Formatter) stripTestPrefix(name string) string {
	if f.cfg.LeaveTestPrefix {
		return name
	}
	if strings.HasPrefix(name, "Test") {
		return strings.TrimPrefix(name, "Test")
	}
	return name
}

func (f *Formatter) labelFor(cat string) (string, string) {
	switch cat {
	case "build":
		return "BUILD", "!!"
	case "start":
		return "START", ">"
	case "pass":
		return "PASS", "o"
	case "fail":
		return "FAIL", "x"
	case "skip":
		return "SKIP", "-"
	case "cover":
		return "COVER", "%"
	case "passPackage":
		return "PASS", "o"
	case "failPackage":
		return "FAIL", "x"
	case "skipPackage":
		return "SKIP", "-"
	default:
		return "", ""
	}
}

func (f *Formatter) styleFor(cat string) ResolvedStyle {
	switch cat {
	case "build":
		return f.cfg.BuildStyle
	case "start":
		return f.cfg.StartStyle
	case "pass":
		return f.cfg.PassStyle
	case "fail":
		return f.cfg.FailStyle
	case "skip":
		return f.cfg.SkipStyle
	case "cover":
		return f.cfg.CoveredStyle
	case "passPackage":
		return f.cfg.PassPackageStyle
	case "failPackage":
		return f.cfg.FailPackageStyle
	case "skipPackage":
		return f.cfg.SkipStyle
	default:
		if f.hasLastStyle {
			return f.lastStyle
		}
		return ResolvedStyle{}
	}
}

func (f *Formatter) buildLabel(cat string) string {
	longLabel, shortLabel := f.labelFor(cat)
	switch f.cfg.LabelType {
	case "short":
		padded := fmt.Sprintf("%-2s", shortLabel)
		return padded + " "
	case "none":
		return ""
	default:
		padded := fmt.Sprintf("%-5s", longLabel)
		return padded + "| "
	}
}

func (f *Formatter) formatWithStyle(style ResolvedStyle, plain string) string {
	if !f.enableColor {
		return plain
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain
	}
	return ansi + plain + "\x1b[0m"
}

func (f *Formatter) formatFileLine(parentStyle ResolvedStyle, raw string) (string, bool) {
	// Apply removals first to raw
	rawAfter := f.applyRemovals(raw)

	// Regex for file
	re := regexp.MustCompile(`^(\s*)(.*\.go):(\d+)(:\d+)?:(.*)$`)
	m := re.FindStringSubmatch(rawAfter)
	if m == nil {
		// No file, generic
		// Check if after removals content is empty -> hide?
		if strings.TrimSpace(rawAfter) == "" {
			return "", true
		}
		label := f.buildLabel("")
		plain := label + rawAfter
		// Apply removals again to final plain for label removals
		for _, r := range f.cfg.Removals {
			plain = r.ReplaceAllString(plain, "")
		}
		trimmed := strings.TrimSpace(plain)
		if trimmed == "" || trimmed == "|" {
			return "", true
		}
		if !f.enableColor {
			return plain, false
		}
		// Color whole with parent
		ansi := parentStyle.toANSI()
		if ansi == "" {
			return plain, false
		}
		return ansi + plain + "\x1b[0m", false
	}
	leading := m[1]
	filePath := m[2]
	lineNum := m[3]
	colPart := m[4]
	rest := m[5]

	// Handle hide for file and line
	if f.cfg.FileStyle.Hide {
		filePath = ""
	}
	if f.cfg.LineStyle.Hide {
		lineNum = ""
		colPart = ""
	}

	// If file hidden and line hidden and rest after trim is empty? Could hide?
	// Build content
	var contentParts []string
	if leading != "" {
		contentParts = append(contentParts, leading)
	}
	content := leading + filePath
	if lineNum != "" {
		content += ":" + lineNum
		if colPart != "" {
			content += colPart
		}
	}
	content += rest

	// For plain without colors, content is as above
	// But we also need label
	label := f.buildLabel("")
	plain := label + content

	// Apply removals to final plain
	for _, r := range f.cfg.Removals {
		plain = r.ReplaceAllString(plain, "")
	}
	if strings.TrimSpace(plain) == "" || strings.TrimSpace(plain) == "|" {
		return "", true
	}

	if !f.enableColor {
		return plain, false
	}

	// Build colored version
	parentANSI := parentStyle.toANSI()
	fileANSI := f.cfg.FileStyle.toANSI()
	lineANSI := f.cfg.LineStyle.toANSI()
	reset := "\x1b[0m"

	var coloredLabel string
	if label != "" {
		if parentANSI != "" {
			coloredLabel = parentANSI + label + reset
		} else {
			coloredLabel = label
		}
	}

	// Build colored content piece by piece, but we have already applied removals to filePath etc? We applied removals to raw earlier, but not to individual parts after hide? Let's apply removals to each part as well? Actually we applied removals to rawAfter which already removed substrings from filePath etc.

	// For coloring, we need to split coloredContent
	var coloredContent string
	// leading
	if leading != "" {
		if parentANSI != "" {
			coloredContent += parentANSI + leading + reset
		} else {
			coloredContent += leading
		}
	}
	if filePath != "" {
		if fileANSI != "" {
			coloredContent += fileANSI + filePath + reset
		} else {
			coloredContent += filePath
		}
	}
	if lineNum != "" {
		lineStr := ":" + lineNum
		if colPart != "" {
			lineStr += colPart
		}
		if lineANSI != "" {
			coloredContent += lineANSI + lineStr + reset
		} else {
			coloredContent += lineStr
		}
	}
	if rest != "" {
		if parentANSI != "" {
			coloredContent += parentANSI + rest + reset
		} else {
			coloredContent += rest
		}
	}

	full := coloredLabel + coloredContent
	return full, false
}

func (f *Formatter) FormatLine(raw string) (string, bool) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return "", false
	}

	// Build detection
	if strings.HasPrefix(raw, "# ") {
		return f.formatBuild(raw)
	}

	// Coverage with percentage
	if strings.HasPrefix(strings.TrimSpace(raw), "coverage:") {
		re := regexp.MustCompile(`coverage:\s+([\d\.]+)% of statements`)
		m := re.FindStringSubmatch(raw)
		if m != nil {
			return f.formatCover(raw, m[1])
		}
		// Else treat as generic continuation (no statements)
	}

	// Test result PASS/FAIL/SKIP with leading spaces
	reTest := regexp.MustCompile(`^(\s*)--- (PASS|FAIL|SKIP):\s+(\S+)(.*)$`)
	if m := reTest.FindStringSubmatch(raw); m != nil {
		leading := m[1]
		verdict := m[2]
		testName := m[3]
		rest := m[4]
		return f.formatTestResult(leading, verdict, testName, rest)
	}

	// RUN
	reRun := regexp.MustCompile(`^=== RUN\s+(\S+)$`)
	if m := reRun.FindStringSubmatch(raw); m != nil {
		return f.formatRun(m[1])
	}

	// PASS bare
	if trimmed == "PASS" {
		return f.formatPassPackageBare(raw)
	}
	if trimmed == "FAIL" {
		return f.formatFailPackageBare(raw)
	}

	// ok package
	if strings.HasPrefix(trimmed, "ok") {
		return f.formatOkPackage(raw)
	}

	// FAIL package with tab
	if strings.HasPrefix(raw, "FAIL\t") || strings.HasPrefix(raw, "FAIL ") {
		return f.formatFailPackage(raw)
	}

	// ? package
	if strings.HasPrefix(trimmed, "?") {
		return f.formatQuestionPackage(raw)
	}

	// Generic
	return f.formatGeneric(raw)
}

func (f *Formatter) formatBuild(raw string) (string, bool) {
	cat := "build"
	style := f.cfg.BuildStyle
	if style.Hide {
		return "", true
	}
	f.lastStyle = style
	f.hasLastStyle = true

	content := strings.TrimPrefix(raw, "# ")
	content = f.applyRemovals(content)

	label := f.buildLabel(cat)
	var plain string
	if f.cfg.LabelType == "none" {
		plain = content
	} else {
		plain = label + content
	}
	for _, re := range f.cfg.Removals {
		plain = re.ReplaceAllString(plain, "")
	}
	if strings.TrimSpace(plain) == "" {
		return "", true
	}
	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + "\x1b[0m", false
}

func (f *Formatter) formatCover(raw, percentStr string) (string, bool) {
	percent, _ := strconv.ParseFloat(percentStr, 64)
	var style ResolvedStyle
	if percent >= float64(f.cfg.CoverThreshold) {
		style = f.cfg.CoveredStyle
	} else {
		style = f.cfg.UncoveredStyle
	}
	if style.Hide {
		return "", true
	}
	f.lastStyle = style
	f.hasLastStyle = true

	hashes := int(percent / 10)
	if hashes > 10 {
		hashes = 10
	}
	if hashes < 0 {
		hashes = 0
	}
	bar := strings.Repeat("#", hashes) + strings.Repeat("_", 10-hashes)
	content := fmt.Sprintf("%s%% [%s]", percentStr, bar)
	content = f.applyRemovals(content)

	label := f.buildLabel("cover")
	var plain string
	if f.cfg.LabelType == "none" {
		plain = content
	} else {
		plain = label + content
	}
	for _, re := range f.cfg.Removals {
		plain = re.ReplaceAllString(plain, "")
	}
	if strings.TrimSpace(plain) == "" {
		return "", true
	}
	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + "\x1b[0m", false
}

func (f *Formatter) formatTestResult(leading, verdict, testName, rest string) (string, bool) {
	var cat string
	switch verdict {
	case "PASS":
		cat = "pass"
	case "FAIL":
		cat = "fail"
	case "SKIP":
		cat = "skip"
	}
	style := f.styleFor(cat)
	if style.Hide {
		return "", true
	}
	f.lastStyle = style
	f.hasLastStyle = true

	stripped := f.stripTestPrefix(testName)
	// Apply removals to stripped name
	stripped = f.applyRemovals(stripped)

	slashCount := strings.Count(stripped, "/")
	indent := strings.Repeat("  ", slashCount)

	// rest contains duration, apply removals to rest as well
	rest = f.applyRemovals(rest)

	content := indent + stripped + rest

	label := f.buildLabel(cat)
	var plain string
	if f.cfg.LabelType == "none" {
		plain = content
	} else {
		plain = label + content
	}
	for _, re := range f.cfg.Removals {
		plain = re.ReplaceAllString(plain, "")
	}
	if strings.TrimSpace(plain) == "" {
		return "", true
	}
	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + "\x1b[0m", false
}

