		return "", true
	}
	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + "\x1b[0m", false
}

func (f *Formatter) formatQuestionPackage(raw string) (string, bool) {
	cat := "skipPackage"
	style := f.cfg.SkipStyle
	if style.Hide {
		return "", true
	}
	f.lastStyle = style
	f.hasLastStyle = true

	trimmed := strings.TrimSpace(raw)
	// Remove leading "?"
	if strings.HasPrefix(trimmed, "?") {
		trimmed = strings.TrimSpace(trimmed[1:])
	}
	// Now trimmed like "example.com/notest [no test files]" or with tab
	// We need to handle that raw had "?   \t pkg"
	// For plain without color, we want content as is after "?"

	content := trimmed
	content = f.applyRemovals(content)

	label := f.buildLabel("skip")
	var plain string
	if f.cfg.LabelType == "none" {
		plain = content
	} else {
		plain = label + content
	}
	for _, r := range f.cfg.Removals {
		plain = r.ReplaceAllString(plain, "")
	}
	if strings.TrimSpace(plain) == "" {
		return "", true
	}
	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + "\x1b[0m", false
}

func (f *Formatter) formatGeneric(raw string) (string, bool) {
	// Use last style if exists
	var style ResolvedStyle
	if f.hasLastStyle {
		style = f.lastStyle
	}

	// Apply removals to raw first
	rawAfter := f.applyRemovals(raw)

	// If after removals empty, hide?
	if strings.TrimSpace(rawAfter) == "" {
		return "", true
	}

	// Check for file pattern
	fileRe := regexp.MustCompile(`^(\s*)(.*\.go):(\d+)(:\d+)?:(.*)$`)
	m := fileRe.FindStringSubmatch(rawAfter)
	if m != nil {
		leading := m[1]
		filePath := m[2]
		lineNum := m[3]
		colPart := m[4]
		rest := m[5]

		if f.cfg.FileStyle.Hide {
			filePath = ""
		}
		if f.cfg.LineStyle.Hide {
			lineNum = ""
			colPart = ""
		}

		// Build plain
		label := f.buildLabel("")
		content := leading + filePath
		if lineNum != "" {
			content += ":" + lineNum
			if colPart != "" {
				content += colPart
			}
		}
		content += rest

		var plain string
		if f.cfg.LabelType == "none" {
			plain = content
		} else {
			plain = label + content
		}
		for _, r := range f.cfg.Removals {
			plain = r.ReplaceAllString(plain, "")
		}
		if strings.TrimSpace(plain) == "" || strings.TrimSpace(plain) == "|" {
			return "", true
		}
		if !f.enableColor {
			return plain, false
		}

		// Colored version
		parentANSI := style.toANSI()
		fileANSI := f.cfg.FileStyle.toANSI()
		lineANSI := f.cfg.LineStyle.toANSI()
		reset := "\x1b[0m"

		var coloredLabel string
		if label != "" {
			if parentANSI != "" {
				coloredLabel = parentANSI + label + reset
			} else {
				coloredLabel = label
			}
		}

		var coloredContent string
		if leading != "" {
			if parentANSI != "" {
				coloredContent += parentANSI + leading + reset
			} else {
				coloredContent += leading
			}
		}
		if filePath != "" {
			if fileANSI != "" {
				coloredContent += fileANSI + filePath + reset
			} else {
				coloredContent += filePath
			}
		}
		if lineNum != "" {
			lineStr := ":" + lineNum
			if colPart != "" {
				lineStr += colPart
			}
			if lineANSI != "" {
				coloredContent += lineANSI + lineStr + reset
			} else {
				coloredContent += lineStr
			}
		}
		if rest != "" {
			if parentANSI != "" {
				coloredContent += parentANSI + rest + reset
			} else {
				coloredContent += rest
			}
		}

		return coloredLabel + coloredContent, false
	}

	// No file
	label := f.buildLabel("")
	plain := label + rawAfter
	for _, r := range f.cfg.Removals {
		plain = r.ReplaceAllString(plain, "")
	}
	trimmed := strings.TrimSpace(plain)
	if trimmed == "" || trimmed == "|" {
		return "", true
	}
	if !f.enableColor {
		return plain, false
	}
	ansi := style.toANSI()
	if ansi == "" {
		return plain, false
	}
	return ansi + plain + reset, false
}

var reset = "\x1b[0m"

func runGo(args []string) int {
	cmd := exec.Command("go", args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	err := cmd.Run()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			return exitErr.ExitCode()
		}
		return 1
	}
	return 0
}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		// Show go help
		code := runGo(args)
		os.Exit(code)
	}

	if args[0] == "testfilter" {
		cfg := loadConfig()
		enable := isTerminal()
		formatter := NewFormatter(cfg, enable)

		scanner := bufio.NewScanner(os.Stdin)
		buf := make([]byte, 0, 1024*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			if !enable {
				fmt.Fprintln(os.Stdout, line)
				continue
			}
			f, hide := formatter.FormatLine(line)
			if hide {
				continue
			}
			fmt.Fprintln(os.Stdout, f)
		}
		return
	}

	if args[0] == "test" {
		cfg := loadConfig()
		enable := isTerminal()

		if !enable {
			code := runGo(args)
			os.Exit(code)
		}

		// Color enabled: need to capture and format
		goArgs := args
		cmd := exec.Command("go", goArgs...)
		stdoutPipe, _ := cmd.StdoutPipe()
		stderrPipe, _ := cmd.StderrPipe()
		cmd.Stdin = os.Stdin

		if err := cmd.Start(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}

		formatterOut := NewFormatter(cfg, true)
		formatterErr := NewFormatter(cfg, true)

		done := make(chan struct{}, 2)

		go func() {
			scanner := bufio.NewScanner(stdoutPipe)
			buf := make([]byte, 0, 1024*1024)
			scanner.Buffer(buf, 10*1024*1024)
			for scanner.Scan() {
				line := scanner.Text()
				f, hide := formatterOut.FormatLine(line)
				if hide {
					continue
				}
				fmt.Fprintln(os.Stdout, f)
			}
			done <- struct{}{}
		}()

		go func() {
			scanner := bufio.NewScanner(stderrPipe)
			buf := make([]byte, 0, 1024*1024)
			scanner.Buffer(buf, 10*1024*1024)
			for scanner.Scan() {
				line := scanner.Text()
				f, hide := formatterErr.FormatLine(line)
				if hide {
					continue
				}
				fmt.Fprintln(os.Stderr, f)
			}
			done <- struct{}{}
		}()

		<-done
		<-done

		err := cmd.Wait()
		if err != nil {
			if exitErr, ok := err.(*exec.ExitError); ok {
				os.Exit(exitErr.ExitCode())
			}
			os.Exit(1)
		}
		return
	}

	// Other subcommands: delegate to go
	code := runGo(args)
	os.Exit(code)
}
