func loadConfig() ResolvedConfig {
	cfg := defaultConfig()
	cwd, _ := os.Getwd()
	gopath := os.Getenv("GOPATH")
	if gopath == "" {
		home, _ := os.UserHomeDir()
		if home != "" {
			gopath = filepath.Join(home, "go")
		}
	} else {
		parts := strings.Split(gopath, string(os.PathListSeparator))
		if len(parts) > 0 {
			gopath = parts[0]
		}
	}
	goroot := os.Getenv("GOROOT")
	if goroot == "" {
		goroot = runtime.GOROOT()
	}
	homeDir, _ := os.UserHomeDir()

	var candidates []string
	if os.Getenv("RICHGO_LOCAL") == "1" {
		candidates = []string{
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
		}
	} else {
		candidates = []string{
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
			filepath.Join(gopath, ".richstyle"),
			filepath.Join(gopath, ".richstyle.yaml"),
			filepath.Join(gopath, ".richstyle.yml"),
			filepath.Join(goroot, ".richstyle"),
			filepath.Join(goroot, ".richstyle.yaml"),
			filepath.Join(goroot, ".richstyle.yml"),
			filepath.Join(homeDir, ".richstyle"),
			filepath.Join(homeDir, ".richstyle.yaml"),
			filepath.Join(homeDir, ".richstyle.yml"),
		}
	}

	var allRemovals []string
	for _, path := range candidates {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		var cf ConfigFile
		if err := yaml.Unmarshal(data, &cf); err != nil {
			continue
		}
		if cf.LabelType != nil {
			cfg.LabelType = strings.ToLower(strings.TrimSpace(*cf.LabelType))
		}
		if cf.CoverThreshold != nil {
			cfg.CoverThreshold = *cf.CoverThreshold
		}
		if cf.LeaveTestPrefix != nil {
			cfg.LeaveTestPrefix = *cf.LeaveTestPrefix
		}
		if cf.BuildStyle != nil {
			mergeStyle(&cfg.BuildStyle, cf.BuildStyle)
		}
		if cf.StartStyle != nil {
			mergeStyle(&cfg.StartStyle, cf.StartStyle)
		}
		if cf.PassStyle != nil {
			mergeStyle(&cfg.PassStyle, cf.PassStyle)
		}
		if cf.FailStyle != nil {
			mergeStyle(&cfg.FailStyle, cf.FailStyle)
		}
		if cf.SkipStyle != nil {
			mergeStyle(&cfg.SkipStyle, cf.SkipStyle)
		}
		if cf.FileStyle != nil {
			mergeStyle(&cfg.FileStyle, cf.FileStyle)
		}
		if cf.LineStyle != nil {
			mergeStyle(&cfg.LineStyle, cf.LineStyle)
		}
		if cf.PassPackageStyle != nil {
			mergeStyle(&cfg.PassPackageStyle, cf.PassPackageStyle)
		}
		if cf.FailPackageStyle != nil {
			mergeStyle(&cfg.FailPackageStyle, cf.FailPackageStyle)
		}
		if cf.CoveredStyle != nil {
			mergeStyle(&cfg.CoveredStyle, cf.CoveredStyle)
		}
		if cf.UncoveredStyle != nil {
			mergeStyle(&cfg.UncoveredStyle, cf.UncoveredStyle)
		}
		if len(cf.Removals) > 0 {
			allRemovals = append(allRemovals, cf.Removals...)
		}
	}
	for _, pat := range allRemovals {
		re, err := regexp.Compile(pat)
		if err != nil {
			panic(fmt.Sprintf("regexp: Compile(`%s`): %v", pat, err))
		}
		cfg.Removals = append(cfg.Removals, re)
	}
	return cfg
}

func colorNameToCode(name string, isBackground bool) (string, bool) {
	lower := strings.ToLower(strings.TrimSpace(name))
	if strings.HasPrefix(lower, "#") || strings.HasPrefix(lower, "rgb(") {
		return "", false
	}
	switch lower {
	case "black":
		if isBackground {
			return "40", true
		}
		return "30", true
	case "red":
		if isBackground {
			return "41", true
		}
		return "31", true
	case "green":
		if isBackground {
			return "42", true
		}
		return "32", true
	case "yellow":
		if isBackground {
			return "43", true
		}
		return "33", true
	case "blue":
		if isBackground {
			return "44", true
		}
		return "34", true
	case "magenta":
		if isBackground {
			return "45", true
		}
		return "35", true
	case "cyan":
		if isBackground {
			return "46", true
		}
		return "36", true
	case "white":
		if isBackground {
			return "47", true
		}
		return "37", true
	case "lightblack", "brightblack", "gray", "grey":
		if isBackground {
			return "100", true
		}
		return "90", true
	case "lightred", "brightred":
		if isBackground {
			return "101", true
		}
		return "91", true
	case "lightgreen", "brightgreen":
		if isBackground {
			return "102", true
		}
		return "92", true
	case "lightyellow", "brightyellow":
		if isBackground {
			return "103", true
		}
		return "93", true
	case "lightblue", "brightblue":
		if isBackground {
			return "104", true
		}
		return "94", true
	case "lightmagenta", "brightmagenta":
		if isBackground {
			return "105", true
		}
		return "95", true
	case "lightcyan", "brightcyan":
		if isBackground {
			return "106", true
		}
		return "96", true
	case "lightwhite", "brightwhite":
		if isBackground {
			return "107", true
		}
		return "97", true
	default:
		return "", false
	}
}

func parseHexColor(s string) (int, int, int, bool) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "#") {
		hex := strings.TrimPrefix(s, "#")
		if len(hex) == 3 {
			r := string(hex[0]) + string(hex[0])
			g := string(hex[1]) + string(hex[1])
			b := string(hex[2]) + string(hex[2])
			hex = r + g + b
		}
		if len(hex) == 6 {
			r, err1 := strconv.ParseInt(hex[0:2], 16, 0)
			g, err2 := strconv.ParseInt(hex[2:4], 16, 0)
			b, err3 := strconv.ParseInt(hex[4:6], 16, 0)
			if err1 == nil && err2 == nil && err3 == nil {
				return int(r), int(g), int(b), true
			}
		}
		return 0, 0, 0, false
	}
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "rgb(") && strings.HasSuffix(lower, ")") {
		inner := strings.TrimSpace(s[4 : len(s)-1])
		parts := strings.Split(inner, ",")
		if len(parts) != 3 {
			return 0, 0, 0, false
		}
		var vals [3]int
		for i, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(strings.ToLower(p), "0x") {
				v, err := strconv.ParseInt(p[2:], 16, 0)
				if err != nil {
					return 0, 0, 0, false
				}
				vals[i] = int(v)
			} else {
				v, err := strconv.Atoi(p)
				if err != nil {
					return 0, 0, 0, false
				}
				vals[i] = v
			}
		}
		return vals[0], vals[1], vals[2], true
	}
	return 0, 0, 0, false
}

func (s ResolvedStyle) toANSI() string {
	var codes []string
	if s.Background != "" {
		if code, ok := colorNameToCode(s.Background, true); ok {
			codes = append(codes, "\x1b["+code+"m")
		} else if r, g, b, ok := parseHexColor(s.Background); ok {
			codes = append(codes, fmt.Sprintf("\x1b[48;2;%d;%d;%dm", r, g, b))
		}
	}
	if s.Foreground != "" {
		if code, ok := colorNameToCode(s.Foreground, false); ok {
			codes = append(codes, "\x1b["+code+"m")
		} else if r, g, b, ok := parseHexColor(s.Foreground); ok {
			codes = append(codes, fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b))
		}
	}
	if s.Bold {
		codes = append(codes, "\x1b[1m")
	}
	if s.Faint {
		codes = append(codes, "\x1b[2m")
	}
	if s.Italic {
		codes = append(codes, "\x1b[3m")
	}
	if s.Underline {
		codes = append(codes, "\x1b[4m")
	}
	if s.BlinkSlow {
		codes = append(codes, "\x1b[5m")
	}
	if s.BlinkRapid {
		codes = append(codes, "\x1b[6m")
	}
	if s.Inverse {
		codes = append(codes, "\x1b[7m")
	}
	if s.Conceal {
		codes = append(codes, "\x1b[8m")
	}
	if s.CrossOut {
		codes = append(codes, "\x1b[9m")
	}
	if s.Frame {
		codes = append(codes, "\x1b[51m")
	}
	if s.Encircle {
		codes = append(codes, "\x1b[52m")
	}
	if s.Overline {
		codes = append(codes, "\x1b[53m")
	}
	return strings.Join(codes, "")
}

func isTerminal() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

type Formatter struct {
	cfg          ResolvedConfig
	enableColor  bool
	lastStyle    ResolvedStyle
	hasLastStyle bool
}

func NewFormatter(cfg ResolvedConfig, enableColor bool) *Formatter {
	return &Formatter{cfg: cfg, enableColor: enableColor}
}

func (f *Formatter) applyRemovals(s string) string {
	for _, re := range f.cfg.Removals {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

func (f *Formatter) stripTestPrefix(name string) string {
	if f.cfg.LeaveTestPrefix {
		return name
	}
	if strings.HasPrefix(name, "Test") {
		return strings.TrimPrefix(name, "Test")
	}
	return name
}

